<?php
require __DIR__.'/config/database.php';function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(($_POST['action']??'')==='add'){$s=$pdo->prepare('INSERT INTO hoc_phan(ma_hoc_phan,ten_hoc_phan,so_tin_chi,khoa_id) VALUES(?,?,?,?)');$s->execute([trim($_POST['ma_hoc_phan']),trim($_POST['ten_hoc_phan']),(int)$_POST['so_tin_chi'],(int)$_POST['khoa_id']]);$msg='Đã thêm học phần.';}elseif(($_POST['action']??'')==='delete'){$s=$pdo->prepare('DELETE FROM hoc_phan WHERE id=?');$s->execute([(int)$_POST['id']]);$msg='Đã xóa học phần.';}}catch(Throwable $e){$err='Không thực hiện được (có thể học phần đang được sử dụng): '.$e->getMessage();}}
$khoas=$pdo->query('SELECT id,ten_khoa FROM khoa ORDER BY ten_khoa')->fetchAll();$rows=$pdo->query('SELECT hp.*,k.ten_khoa FROM hoc_phan hp JOIN khoa k ON k.id=hp.khoa_id ORDER BY hp.id DESC')->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Học phần - ExamFlow</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="layout"><aside class="sidebar"><div class="brand">▦ ExamFlow</div><a href="index.php">Tổng quan</a><a href="students.php">Sinh viên</a><a class="active" href="courses.php">Học phần</a><a href="exams.php">Kỳ thi & ca thi</a><a href="rooms.php">Phòng thi</a><a href="results.php">Kết quả thi</a></aside><main class="main"><div class="top"><div><h1>Quản lý học phần</h1><div class="muted">Danh sách học phần đang có trong MySQL.</div></div><a class="btn secondary" href="index.php">← Tổng quan</a></div><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif?><?php if($err):?><div class="notice error"><?=h($err)?></div><?php endif?><div class="panel"><h2>Thêm học phần</h2><form method="post"><input type="hidden" name="action" value="add"><div class="formgrid"><div><label>Mã học phần</label><input name="ma_hoc_phan" required maxlength="15"></div><div><label>Tên học phần</label><input name="ten_hoc_phan" required maxlength="150"></div><div><label>Số tín chỉ</label><input type="number" name="so_tin_chi" min="1" required></div><div><label>Khoa quản lý</label><select name="khoa_id" required><?php foreach($khoas as $k):?><option value="<?=$k['id']?>"><?=h($k['ten_khoa'])?></option><?php endforeach?></select></div></div><button class="btn">Thêm học phần</button></form></div><div class="panel"><h2>Danh sách học phần (<?=count($rows)?>)</h2><table><thead><tr><th>Mã học phần</th><th>Tên học phần</th><th>Tín chỉ</th><th>Khoa</th><th>Thao tác</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['ma_hoc_phan'])?></td><td><?=h($r['ten_hoc_phan'])?></td><td><?=h($r['so_tin_chi'])?></td><td><?=h($r['ten_khoa'])?></td><td><form method="post" onsubmit="return confirm('Xóa học phần này?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Xóa</button></form></td></tr><?php endforeach?></tbody></table></div></main></div></body></html>
